// === Tab: mySketch ===
// let Risou
// https://risoume.github.io

color[][] colors = {{"#A16F00", "#FFAF00", "#ffffff"}, {"#0A538F", "#108BEF", "#ffffff"}, {"#ffffff", "#212121", "#444444"}};

let n, k, c;
let m = 80;
let s;
let off = 5;

let grids;

function setup() {
  createCanvas(600, 600);
  noLoop();
  init();
}

function init() {
  n = 3;
  grids = new Array(4*n*n);
  s = (width-2*m)/n;
  off = s*0.02;
  k = 0;

  for (i = m; i < width-2*m; i += s) {
    for (j = m; j < width-2*m; j += s) {
      if (random(1) < 0.5) {
        grids[k] = new Grid(i, j, s);
        k++;
      } else {
        grids[k] = new Grid(i, j, s/2);
        grids[k+1] = new Grid(i+s/2, j, s/2);
        grids[k+2] = new Grid(i, j+s/2, s/2);
        grids[k+3] = new Grid(i+s/2, j+s/2, s/2);
        k += 4;
      }
    }
  }
}

function draw() {
  c = int(random(colors.length));
  background(colors[c][1]);
  let r1 = 4;
  let r1Shadow = 3*r1;
  for (i = 0; i < k; i++) {
    let points = int(random(9, 22));
    grids[i].display(r1Shadow, points, off, colors[c][0]);
    grids[i].display(r1, points, 0, colors[c][1]);
  }
}

class Grid {
  x, y, size;

  constructor(tx, ty, ts) {
    x = tx;
    y = ty;
    size = ts;
  }

  function display(r1, n, off, col) {
    noFill();
    stroke(colors[c][2]);
    strokeWeight(4);
    rect(x, y, size, size);

    stroke(0);
    strokeWeight(1);
    pushMatrix();
    translate(x+size/2+off, y+size/2+off);
    fill(col);
    let r2 = size*0.4;
    let angle = TWO_PI / n;
    let halfAngle = angle/2.0;

    beginShape();
    for (a = 0; a < TWO_PI; a += angle) {
      let sx = cos(a) * r2;
      let sy = sin(a) * r2;
      vertex(sx, sy);
      sx = cos(a+halfAngle) * r1;
      sy = sin(a+halfAngle) * r1;
      vertex(sx, sy);
    }
    endShape(CLOSE);
    popMatrix();
  }
}

function mouseReleased() {
  init();
  redraw();
}

